function contextualGreeting(){const now=new Date(),h=now.getHours(),md=`${now.getMonth()+1}-${now.getDate()}`,special={'1-1':'Selamat Tahun Baru','5-1':'Selamat Hari Buruh','6-1':'Selamat Hari Lahir Pancasila','8-17':'Dirgahayu Republik Indonesia','10-2':'Selamat Hari Batik Nasional','11-10':'Selamat Hari Pahlawan','12-25':'Selamat Hari Natal'}[md];if(special)return special;return h<11?'Selamat pagi':h<15?'Selamat siang':h<18?'Selamat sore':'Selamat malam'}
function loadKapuasCatalog(){if(state.ckan.status==='siap')return;const cb='sababukaCkan'+Date.now(),script=document.createElement('script');window[cb]=payload=>{state.ckan={status:payload?.success?'siap':'gagal',count:payload?.result?.count||0,items:(payload?.result?.results||[]).slice(0,5)};delete window[cb];script.remove();render()};script.onerror=()=>{state.ckan.status='gagal';delete window[cb];script.remove();render()};script.src=`https://satudata.kapuaskab.go.id/api/3/action/package_search?rows=5&sort=metadata_modified%20desc&callback=${cb}`;document.head.appendChild(script)}
async function loadBpsCatalog(){const apiKey=window.SABABUKA_CONFIG?.bpsApiKey;if(!apiKey||state.bps.status==='memuat'||state.bps.status==='siap')return;state.bps.status='memuat';try{const result=await getBpsPublications({apiKey,year:state.year});state.bps={status:'siap',total:result.total,items:result.items.slice(0,3).map(item=>({title:item.title,url:item.pdf||'https://kapuaskab.bps.go.id/id/publication',type:'Publikasi WebAPI'}))}}catch(error){state.bps.status='gagal';console.warn('BPS connector:',error.message)}render()}
async function loadMapGeometry(){if(state.geo||state.geoStatus==='gagal')return;try{const response=await fetch('./src/data/kapuas-kecamatan.geojson');if(!response.ok)throw new Error('GeoJSON tidak dapat dimuat');state.geo=await response.json();state.geoStatus='siap'}catch(error){state.geoStatus='gagal';console.warn('Peta kecamatan:',error.message)}if(state.page==='map')render()}
function liveSourcePanel(){const target=state.role==='bapperida'?'validation':'sources',executive=state.page==='summary';return `<section class="source-trust" aria-label="Jejak sumber dashboard"><div class="source-trust-intro"><span class="eyebrow">Jejak sumber data</span><h2>${executive?'Sumber setiap indikator dapat ditelusuri':'Sumber, kanal, dan status integrasi dibedakan'}</h2><p>${executive?'Ringkasan menggunakan statistik resmi, katalog daerah, dan data sektoral yang telah melalui kendali mutu.':'BPS adalah rujukan statistik; Satu Data adalah katalog/kanal; OPD tetap menjadi produsen substansi.'}</p></div><a class="source-channel bps" href="https://kapuaskab.bps.go.id/id" target="_blank" rel="noopener"><span class="channel-mark">BPS</span><strong>BPS Kabupaten Kapuas</strong><small>${executive?'Statistik resmi dan publikasi daerah':'Rujukan statistik aktif'}</small><em>BUKA SUMBER RESMI ↗</em></a><a class="source-channel" href="https://satudata.kapuaskab.go.id" target="_blank" rel="noopener"><span class="channel-mark">SD</span><strong>Satu Data Kabupaten Kapuas</strong><small>${state.ckan.status==='siap'?`${fmt(state.ckan.count)} dataset dalam katalog`:'Katalog data daerah'}</small><em>BUKA KATALOG ↗</em></a><button class="source-channel" data-page="${target}"><span class="channel-mark">KT</span><strong>${executive?'Terkurasi BAPPERIDA':'Kelayakan tayang'}</strong><small>${executive?'Definisi, periode, dan sumber telah diperiksa':'Konfirmasi OPD dan kurasi BAPPERIDA'}</small><em>${state.role==='bapperida'&&!executive?'BUKA ANTREAN':'LIHAT JEJAK'} →</em></button></section>`}
function executiveDecisionBrief(){const priorities=strategicIssues.filter(item=>item.group==='Prioritas Pimpinan');return `<section class="decision-cockpit executive-priority"><div class="decision-heading"><div><span class="eyebrow">Perlu arahan pimpinan</span><h2>Empat fokus utama</h2></div><div class="confidence-stamp"><span>STATUS</span><strong>4</strong><small>fokus aktif</small></div></div><div class="decision-list">${priorities.map((item,i)=>`<button class="decision-item ${item.status==='Kritis'?'critical':i===3?'watch':'warning'}" data-page="analysis"><span>0${i+1}</span><div><small>${item.metric}</small><strong>${item.title}</strong><em>${item.value} · ${item.target}</em><span class="decision-ask">${item.decision}</span></div><b>→</b></button>`).join('')}</div><div class="decision-footer"><span><i class="ok"></i> Sumber dan periode terverifikasi</span><span><i class="wait"></i> Tindak lanjut lintas OPD</span><button data-page="analysis">Buka seluruh analisis</button></div></section>`}
function strategicMonitoringPanel(){const items=strategicIssues.filter(item=>item.group!=='Prioritas Pimpinan');return `<section class="strategic-monitor compact-monitor"><div class="strategic-monitor-head"><div><span class="eyebrow">Pemantauan berkala</span><h2>Fokus strategis lainnya</h2></div><button class="btn" data-page="analysis">Lihat seluruh fokus</button></div><div class="monitor-grid">${items.map(item=>`<article class="monitor-card"><div><span>${item.group}</span>${badge(item.status)}</div><h3>${item.title}</h3><strong>${item.value}</strong><small>${item.metric} · ${item.target}</small><p><b>${item.lead}</b></p></article>`).join('')}</div></section>`}
function strategicIssueMatrix(){return `<section class="card strategic-matrix"><div class="card-title"><div><span class="eyebrow">Portofolio isu lintas OPD</span><h3>Delapan fokus, peran perangkat daerah tetap jelas</h3></div><span>Bukan ranking OPD</span></div><div class="issue-rows">${strategicIssues.map((item,index)=>`<div class="issue-row"><span class="issue-no">${String(index+1).padStart(2,'0')}</span><div><strong>${item.title}</strong><small>${item.metric}: ${item.value} · ${item.target}</small><span class="data-status-line">${issueDataStatus(item)}</span></div><div><span>Pengampu</span><strong>${item.lead}</strong></div><div><span>Pendukung</span><small>${item.support}</small></div>${badge(item.status)}</div>`).join('')}</div></section>`}
function applyYear(year){const index=years.indexOf(year),distance=years.length-1-index;indicators.forEach((item,itemIndex)=>{const base=baseDataset.indicators[itemIndex];item.value=base.trend[index];item.prev=base.trend[Math.max(0,index-1)];const targetFactor=base.higher?.88+index*.03:1.20-index*.05;item.target=+(base.target*targetFactor).toFixed(2);const progress=base.higher?item.value/item.target:item.target/item.value;item.status=progress>=1?'good':progress>=.96?'attention':'critical';item.period=base.period.replace('2026',String(year));item.updated=`${20+itemIndex%8} Agu ${year}`});districts.forEach((item,itemIndex)=>{const base=baseDataset.districts[itemIndex],variation=((itemIndex%3)-1)*(distance%2);item.score=Math.max(45,Math.min(95,Math.round(base.score-distance*(1.4+(itemIndex%4)*.25)+variation)));item.poverty=+(base.poverty+distance*(.18+(itemIndex%3)*.04)-variation*.03).toFixed(1);item.stunting=Math.round(base.stunting+distance*(1.1+(itemIndex%4)*.25)-variation*.2);item.roads=Math.max(35,Math.round(base.roads-distance*(2.1+(itemIndex%3)*.35)+variation))});opds.forEach((item,itemIndex)=>{const base=baseDataset.opds[itemIndex],variation=((itemIndex%4)-1.5)*(distance%2);item.score=Math.max(55,Math.min(98,Math.round(base.score-distance*(1.2+(itemIndex%3)*.35)+variation)));item.status=item.score>=82?'Baik':'Perlu Perhatian';item.updated=year===2026?base.updated:`Data ${year}`});const volumeFactors=[.76,.83,.89,.95,1];services.forEach((item,itemIndex)=>{const base=baseDataset.services[itemIndex],factor=volumeFactors[index],variation=1+(((itemIndex%3)-1)*.015*distance);item.volume=Math.round(base.volume*factor*variation);item.done=Math.round(item.volume*(base.done/base.volume-(distance*.008)));item.satisfaction=+(base.satisfaction-distance*(.7+(itemIndex%2)*.2)).toFixed(1);item.time=+(base.time+distance*(.12+(itemIndex%3)*.03)).toFixed(1)});const financeFactors=[.72,.79,.86,.93,1],factor=financeFactors[index];finance.income=+(baseDataset.finance.income*factor).toFixed(2);finance.budget=+(baseDataset.finance.budget*(.82+index*.045)).toFixed(2);finance.spend=+(baseDataset.finance.spend*factor*(.96+index*.01)).toFixed(3);finance.absorption=+(finance.spend/finance.budget*100).toFixed(1);finance.targetIncome=+(baseDataset.finance.targetIncome*factor).toFixed(2);finance.monthly=baseDataset.finance.monthly.map((value,month)=>+(value*(.90+index*.025)+((month%2?1:-1)*distance*.55)).toFixed(1))}
function toast(msg,type='success'){const el=document.createElement('div');el.className='toast '+type;el.textContent=msg;document.querySelector('#toast-root').appendChild(el);setTimeout(()=>el.remove(),2600)}
function icon(c){return `<span aria-hidden="true">${c}</span>`}
function sidebar(){const menu=menus[state.role],info=roleInfo[state.role];return `<aside class="sidebar ${state.collapsed?'collapsed':''} ${state.mobile?'mobile-open':''}"><div class="brand"><div class="brand-mark">S</div><div class="brand-text"><strong>SABABUKA</strong><span>${info.brand}<br>Kabupaten Kapuas</span></div></div><nav aria-label="Navigasi utama">${menu.map(m=>m[0]==='section'?`<div class="nav-section">${m[2]}</div>`:`<button class="nav-item ${state.page===m[0]?'active':''}" data-page="${m[0]}" aria-label="${m[2]}"><span class="nav-icon">${m[1]}</span><span class="nav-label">${m[2]}</span></button>`).join('')}</nav><div class="sidebar-foot"><button class="nav-item" id="collapseBtn"><span class="nav-icon">${state.collapsed?'»':'«'}</span><span class="nav-label">Perkecil sidebar</span></button></div></aside>`}
function header(){const fixed=fixedPeriodPages.has(state.page),info=roleInfo[state.role];return `<header class="topbar"><button class="icon-btn mobile-menu" id="mobileMenu" aria-label="Buka navigasi">☰</button><div class="topbar-left"><div><div class="topbar-title">${titleMap[state.page]}</div><div class="topbar-meta"><strong>SABABUKA BERSINAR</strong> · Sistem Integrasi Data Daerah</div></div></div><div class="spacer"></div><div class="top-controls"><label class="workspace-switcher" title="Pindah dashboard"><span>Pindah dashboard</span><select class="select role-select" id="roleSelect" aria-label="Pindah dashboard">${Object.entries(roleSwitcherLabels).map(([role,label])=>`<option value="${role}" ${state.role===role?'selected':''}>${label}</option>`).join('')}</select></label><span class="topbar-meta period">${fixed?'Data per Agustus 2026':`Periode Agustus ${state.year}`}</span><select class="select" id="yearSelect" aria-label="Filter tahun" ${fixed?'disabled title="Periode mengikuti pembaruan terakhir halaman"':''}>${years.map(y=>`<option ${y===state.year?'selected':''}>${y}</option>`).join('')}</select><button class="icon-btn" id="searchBtn" aria-label="Pencarian">⌕</button><button class="btn soft presentation-btn" id="presentationBtn">▣ ${state.presentation?'Keluar Presentasi':'Mode Presentasi'}</button><div class="profile ${state.profile?'open':''}" id="profile"><div class="avatar">${info.avatar}</div><div><div class="profile-name">${info.name}</div><div class="profile-role">${info.detail}</div></div><div class="profile-menu"><button data-action="help">Panduan Presentasi</button></div></div></div></header>`}
function metricCard(label,value,delta,tone,ico){return `<article class="metric" data-action="metric"><div class="metric-top"><div class="label">${label}</div><div class="metric-icon ${tone}">${ico}</div></div><div class="value">${value}</div><div class="delta">${delta}</div></article>`}
function badge(status){const c=['Baik','Terhubung','Selesai','Tercapai','Disetujui'].includes(status)?'good':['Kritis','Bermasalah','Perlu Tindak Lanjut','Ditolak'].includes(status)?'critical':'attention';return `<span class="badge ${c}">${status}</span>`}
function indicatorCard(i){let change=i.value-i.prev;let positive=i.higher?change>=0:change<=0;const dataState=indicatorDataState(i),contract=sourceContracts[i.id];return `<article class="indicator indicator-clickable" data-detail="indicator:${i.id}" tabindex="0" role="button" aria-label="Buka penjelasan ${i.name}"><div class="indicator-head"><div><div class="indicator-name">${i.name}</div><small class="indicator-source">${contract.primary} · ${dataState.detail}</small></div><span class="data-seal ${dataState.tone}">${dataState.label}</span></div><div class="indicator-value">${fmt(i.value)} <small>${i.unit}</small></div><div class="indicator-row"><span>Target ${fmt(i.target)} ${i.unit}</span>${badge(statusLabel(i.status))}</div><div class="progress"><span class="status-${statusClass(i.status)}" style="width:${pct(i)}%"></span></div><div class="indicator-row"><span class="${positive?'trend-up':'trend-down'}">${change>=0?'↑':'↓'} ${fmt(Math.abs(change))} dari periode sebelumnya</span><span>${pct(i)}%</span></div><div class="indicator-row"><span class="opd">${i.opd}</span><span>${contract.granularity}</span></div></article>`}
function trendChart(){const map={Ekonomi:'growth',Kemiskinan:'poverty',Kesehatan:'stunting',Pendidikan:'hdi'};const i=indicators.find(x=>x.id===map[state.chartTab]);const max=Math.max(...i.trend,i.target)*1.18;return `<div class="tabs">${Object.keys(map).map(t=>`<button class="tab ${state.chartTab===t?'active':''}" data-tab="${t}">${t}</button>`).join('')}</div><div class="chart" aria-label="Grafik tren ${state.chartTab}">${i.trend.map((v,idx)=>`<div class="bar-col"><div class="bar" style="height:${v/max*100}%" data-tip="${years[idx]}: ${fmt(v)} ${i.unit}"></div><div class="bar target" style="height:${i.target/max*100}%" data-tip="Target: ${fmt(i.target)}"></div><span class="axis-label">${years[idx]}</span></div>`).join('')}</div><div style="margin-top:24px;font-size:11px;color:var(--muted)">Nilai ${years.at(-1)} <strong style="color:var(--ink)">${fmt(i.value)} ${i.unit}</strong> · Target <strong style="color:var(--ink)">${fmt(i.target)} ${i.unit}</strong></div>`}
const mapIndicators={score:{label:'Indeks Komposit',unit:'poin',value:d=>d.score,level:v=>v>=80?'good':v>=68?'attention':'critical'},poverty:{label:'Kemiskinan',unit:'%',value:d=>d.poverty,level:v=>v<=4?'good':v<=5.5?'attention':'critical'},stunting:{label:'Stunting',unit:'%',value:d=>d.stunting,level:v=>v<=18?'good':v<=23?'attention':'critical'},roads:{label:'Jalan Mantap',unit:'%',value:d=>d.roads,level:v=>v>=75?'good':v>=60?'attention':'critical'}};
const mapIndicator=()=>mapIndicators[state.mapIndicator]||mapIndicators.score;
const mapColor=level=>level==='good'?'var(--green)':level==='attention'?'var(--amber)':'var(--red)';
function districtGrid(){const metric=mapIndicator();return `<div class="legend"><span><i class="mini-dot" style="background:var(--green)"></i>Baik</span><span><i class="mini-dot" style="background:var(--amber)"></i>Perlu perhatian</span><span><i class="mini-dot" style="background:var(--red)"></i>Prioritas</span></div><div class="map-grid" style="margin-top:12px">${districts.map(d=>{const value=metric.value(d);return `<button class="district ${state.district===d.name?'active':''}" data-district="${d.name}"><i class="district-status" style="background:${mapColor(metric.level(value))}"></i><strong>${d.name}</strong><span>${metric.label} ${fmt(value)} ${metric.unit}</span></button>`}).join('')}</div>`}
const normalizeDistrictName=name=>String(name||'').toUpperCase().replace(/[^A-Z]/g,'');
function geometryRings(geometry){if(!geometry)return [];return geometry.type==='Polygon'?geometry.coordinates:geometry.type==='MultiPolygon'?geometry.coordinates.flat():[]}
function geographicMap(){
  const metric=mapIndicator();
  if(state.geoStatus==='gagal')return `<div class="map-unavailable"><strong>Peta belum dapat dimuat</strong><p>Gunakan tabel kecamatan di bawah sebagai tampilan cadangan.</p></div>`;
  if(!state.geo)return `<div class="map-loading"><div class="skeleton"></div><span>Memuat batas administrasi 17 kecamatan…</span></div>`;
  const features=state.geo.features||[],points=features.flatMap(feature=>geometryRings(feature.geometry).flat());
  const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys),width=620,height=680,pad=18,scale=Math.min((width-pad*2)/(maxX-minX),(height-pad*2)/(maxY-minY));
  const project=([x,y])=>[pad+(x-minX)*scale,height-pad-(y-minY)*scale];
  const pathFor=geometry=>geometryRings(geometry).map(ring=>ring.map((point,index)=>`${index?'L':'M'}${project(point).map(n=>n.toFixed(1)).join(',')}`).join(' ')+' Z').join(' ');
  const regions=features.map(feature=>{const raw=feature.properties?.Kecamatan||feature.properties?.KECAMATAN||'',district=districts.find(item=>normalizeDistrictName(item.name)===normalizeDistrictName(raw));if(!district)return '';const value=metric.value(district),status=metric.level(value);return `<path class="geo-region ${state.district===district.name?'selected':''}" data-district="${district.name}" d="${pathFor(feature.geometry)}" style="--region-fill:${mapColor(status)}"><title>${district.name} · ${metric.label}: ${fmt(value)} ${metric.unit}</title></path>`}).join('');
  return `<div class="legend map-legend"><span><i class="mini-dot" style="background:var(--green)"></i>Baik</span><span><i class="mini-dot" style="background:var(--amber)"></i>Perlu perhatian</span><span><i class="mini-dot" style="background:var(--red)"></i>Prioritas</span></div><div class="geo-map-wrap"><svg class="geo-map" viewBox="0 0 ${width} ${height}" role="img" aria-label="Peta tematik 17 kecamatan Kabupaten Kapuas">${regions}</svg><div class="map-source">Batas administrasi: FeatureServer Kabupaten Kapuas · visualisasi awal</div></div>`;
}
function alertsList(limit=5){return `<div class="alert-list">${alerts.slice(0,limit).map(a=>`<div class="alert"><div class="alert-strip" style="background:${a.urgency==='Kritis'?'var(--red)':a.urgency==='Tinggi'?'var(--amber)':'#4388cc'}"></div><div><div class="alert-title">${a.title}</div><div class="alert-meta">${a.opd} · ${a.time} · ${a.urgency}</div></div><button class="btn" data-detail="alert:${a.id}">Tinjau</button></div>`).join('')}</div>`}
function validatedAlertsPanel(){const reviewed=alerts.filter(a=>a.status==='Ditinjau').slice(0,3),target=state.role==='bapperida'?'alerts':'analysis';return `<section class="card executive-alerts"><div class="card-title"><div><span class="eyebrow">Peringatan aktif</span><h3>Perlu perhatian</h3></div><button class="btn" data-page="${target}">Lihat semua</button></div><div class="alert-list">${reviewed.map(a=>`<div class="alert"><div class="alert-strip" style="background:${a.urgency==='Kritis'?'var(--red)':a.urgency==='Tinggi'?'var(--amber)':'#4388cc'}"></div><div><div class="alert-title">${a.title}</div><div class="alert-meta">${a.opd} · ${a.urgency}</div></div><button class="btn" data-detail="alert:${a.id}">Lihat</button></div>`).join('')}</div></section>`}
function executiveRegionPanel(){const priority=[...districts].sort((a,b)=>a.score-b.score).slice(0,4);return `<section class="card region-watch"><div class="card-title"><div><span class="eyebrow">Perbandingan wilayah</span><h3>Kecamatan yang perlu dicermati</h3></div><button class="btn" data-page="map">Buka peta</button></div><div class="region-watch-list">${priority.map((d,i)=>`<button data-detail="district:${encodeURIComponent(d.name)}"><span>0${i+1}</span><div><strong>${d.name}</strong><small>Kemiskinan ${d.poverty}% · Stunting ${d.stunting}% · Jalan ${d.roads}%</small></div><b>${d.score}</b></button>`).join('')}</div></section>`}
function opdTable(){return `<div class="table-wrap"><table><thead><tr><th>OPD</th><th>Jumlah Indikator</th><th>Capaian</th><th>Status Data</th><th>Pembaruan</th><th>Aksi</th></tr></thead><tbody>${opds.slice(0,7).map(o=>`<tr><td><strong>${o.name}</strong></td><td>${o.count}</td><td>${o.score}%</td><td>${badge(o.status)}</td><td>${o.updated}</td><td><button class="btn" data-detail="opd:${o.id}">Detail</button></td></tr>`).join('')}</tbody></table></div>`}
function summary(){const crit=indicators.filter(i=>i.status==='critical').length,good=indicators.filter(i=>i.status==='good').length,keyIds=new Set(['growth','poverty','stunting','roads','budget','satisfaction']),keyIndicators=indicators.filter(i=>keyIds.has(i.id));return `<section class="executive-hero executive-hero-compact"><div><span class="eyebrow">RINGKASAN PIMPINAN · AGUSTUS 2026</span><h1>${contextualGreeting()}, Bapak Bupati</h1><div class="hero-tags"><span>● Diperbarui 28 Agustus, 07.45 WIB</span><span>● Terkurasi BAPPERIDA</span></div></div><div class="hero-actions"><button class="btn light" data-action="report">Unduh brief</button><button class="btn outline-light" data-page="assistant">Tanya Asisten Data</button></div></section><div class="metrics executive-metrics command-metrics">${metricCard('Fokus Utama',4,'Memerlukan arahan pimpinan','green','✓')}${metricCard('Kinerja Baik',good,`Dari ${indicators.length} indikator`,'blue','↗')}${metricCard('Sinyal Kritis',crit,'Perlu koordinasi lintas OPD','red','!')}${metricCard('Wilayah Terpantau',districts.length,'Kecamatan Kabupaten Kapuas','blue','⌖')}</div>${executiveDecisionBrief()}<div class="executive-command-grid">${validatedAlertsPanel()}${executiveRegionPanel()}</div><div class="section-head executive-section-head"><div><span class="eyebrow">Indikator kunci</span><h2>Kondisi daerah saat ini</h2></div><div class="filterbar"><button class="btn" data-page="map">Peta wilayah</button><button class="btn" data-page="analysis">Analisis lengkap</button></div></div><div class="indicator-grid executive-indicators">${keyIndicators.map(indicatorCard).join('')}</div><div class="two-col executive-bottom"><div class="card"><div class="card-title"><h3>Tren Strategis 2022–2026</h3><span>Realisasi dan target</span></div>${trendChart()}</div>${strategicMonitoringPanel()}</div><div class="executive-source-line"><span>Jejak data: BPS Kabupaten Kapuas, Satu Data Kabupaten Kapuas, dan data sektoral OPD</span><button data-page="sources">Lihat sumber</button></div>`}
function meetingSummary(){
  let html=summary().replace('SABABUKA COMMAND BRIEF','RINGKASAN EKSEKUTIF DAERAH').replace('Satu pandangan untuk membaca kondisi daerah, memastikan sumber data, dan menentukan tindak lanjut lintas perangkat daerah.','Satu tampilan untuk membaca kondisi daerah, menelusuri sumber data, dan mengarahkan tindak lanjut lintas perangkat daerah.').replace('● Disaring BAPPERIDA','● Kendali mutu berjenjang').replace('Lihat rekomendasi','Lihat bahan analisis').replace('Lolos verifikasi BAPPERIDA','Telah melalui verifikasi').replace('Membutuhkan keputusan lintas OPD','Memerlukan perhatian dan koordinasi').replace('Tidak dipakai sebagai dasar final','Menunggu konfirmasi produsen data').replace('Indikator strategis terkurasi','Indikator strategis daerah').replace('Setiap angka membawa sumber, periode, status verifikasi, target, dan pemilik tindak lanjut.','Setiap indikator dilengkapi sumber, periode, status verifikasi, target, dan penanggung jawab tindak lanjut.').replace('Lihat kendali mutu','Lihat verifikasi data');
  if(state.role==='bupati')html=html.replaceAll('data-page="validation"','data-page="sources"').replaceAll('data-page="alerts"','data-page="analysis"');
  const riskyStart='<div class="two-col"><div class="card"><div class="card-title"><h3>Wilayah yang Perlu Dicermati';
  const safeResume='<section class="source-governance">';
  const start=html.indexOf(riskyStart),resume=html.indexOf(safeResume,start);
  if(start>=0&&resume>start)html=html.slice(0,start)+html.slice(resume);
  return html;
}
