function meetingSources(){return sourcesPage().replace('Sumber Data','Sumber & Integrasi Data').replace('Registry sumber resmi, jalur integrasi, dan status kesiapan','Daftar sumber, jalur pertukaran, serta status kesiapan data daerah').replace('Rujukan Publik BPS','Rujukan Statistik BPS').replace('Website OPD Diaudit','Sumber OPD Dipetakan').replace('OPD Prioritas','Sumber Data OPD').replace('Audit akses publik 12 September 2026','Pemetaan awal kanal dan kesiapan integrasi').replace('Catatan Audit','Catatan Integrasi').replaceAll('Perlu Endpoint','Perlu Kesepakatan Akses')}
