function coordinationPageBase(){const waiting=validations.filter(v=>v.status==='Menunggu').length,newAlerts=alerts.filter(a=>a.status==='Baru').length,needsFollowup=opds.filter(o=>opdDimensions(o).status==='Perlu Tindak Lanjut').length;return `${commonHead('Dashboard BAPPERIDA','Ruang kurasi untuk menyelaraskan kebutuhan kebijakan, konfirmasi OPD, rekonsiliasi sumber, dan kelayakan tayang',`<button class="btn" data-page="indicators">Kamus Indikator</button><button class="btn" data-page="summary">Ringkasan Pimpinan</button><button class="btn primary" data-page="validation">Buka Antrean Kurasi</button>`)}<section class="coordination-hero"><div><span class="eyebrow">Kendali sebelum tayang</span><h2>Pastikan sumber jelas, substansi dikonfirmasi, dan perbedaan direkonsiliasi.</h2><p>BAPPERIDA menentukan kelayakan penyajian untuk konteks pimpinan—bukan mengambil alih kepemilikan atau kewenangan substansi OPD.</p></div><div class="coordination-score readiness-score"><span>Kesiapan indikator prioritas</span><strong>10/12</strong><small>sepuluh indikator telah memenuhi kelengkapan utama</small></div></section><div class="readiness-strip"><div><strong>12</strong><span>Sumber primer ditetapkan</span></div><div><strong>12</strong><span>Metadata tersedia</span></div><div><strong>12</strong><span>Dataset terpetakan</span></div><div><strong>10</strong><span>Konfirmasi OPD</span></div><div><strong>10</strong><span>Layak tayang</span></div></div><div class="metrics">${metricCard('Menunggu Konfirmasi',waiting,'Produsen data perlu memeriksa','amber','◴')}${metricCard('Peringatan Baru',newAlerts,'Belum diteruskan ke pimpinan','red','!')}${metricCard('Kasus Rekonsiliasi',2,'Perbedaan sumber/metode','blue','⇆')}${metricCard('Fokus Lintas OPD',strategicIssues.length,'Peran pengampu dan pendukung','green','✓')}</div><div class="two-col"><div class="card"><div class="card-title"><div><span class="eyebrow">Agenda kurasi</span><h3>Prioritas sumber, konfirmasi, dan rekonsiliasi</h3></div><button class="btn" data-page="validation">Lihat semua</button></div><div class="work-queue"><button data-page="indicators"><span>01</span><div><strong>Lengkapi kontrak sumber indikator</strong><small>Definisi, sumber primer, kanal, frekuensi, granularitas, dan PIC</small></div><b>12 indikator</b></button><button data-page="validation"><span>02</span><div><strong>Konfirmasi stunting, jalan, pangan, dan DTSEN</strong><small>OPD memastikan substansi; BAPPERIDA menilai kelayakan tayang</small></div><b>${waiting} antrean</b></button><button data-page="reconciliation"><span>03</span><div><strong>Rekonsiliasi nilai antar-sumber</strong><small>Versi tidak ditimpa; alasan pemilihan nilai rujukan dicatat</small></div><b>2 kasus</b></button></div></div><div class="card"><div class="card-title"><h3>Alur Tayang ke Pimpinan</h3><span>Jejak tanggung jawab</span></div><div class="vertical-flow"><div class="done"><i>1</i><div><strong>Pemeriksaan teknis</strong><small>Diskominfosantik: koneksi, format, metadata</small></div></div><div class="active"><i>2</i><div><strong>Konfirmasi substansi</strong><small>OPD: nilai, definisi, periode, konteks</small></div></div><div><i>3</i><div><strong>Kurasi BAPPERIDA</strong><small>Rekonsiliasi dan kelayakan untuk pimpinan</small></div></div><div><i>4</i><div><strong>Ringkasan pimpinan</strong><small>Hanya data layak tayang</small></div></div></div></div></div>`}
function coordinationPage(){return coordinationPageBase()+strategicIssueMatrix()}
function indicatorRegistryPage(){return `${commonHead('Fokus & Kamus Indikator','Definisi, pemilik substansi, sumber primer, dan kebutuhan data wilayah untuk setiap indikator',`<button class="btn" data-page="sources">Periksa sumber</button><button class="btn primary" data-page="validation">Lanjut ke kurasi</button>`)}<section class="integration-policy"><div><strong>Berangkat dari kebutuhan kebijakan</strong><p>Indikator dipilih karena membantu menjawab fokus Bupati dan kebutuhan pembangunan daerah.</p></div><div><strong>Peran tetap jelas</strong><p>OPD menjaga substansi, Diskominfosantik menjaga pertukaran data, dan BAPPERIDA menetapkan kelayakan penyajian.</p></div></section><div class="readiness-strip"><div><strong>8</strong><span>Fokus kebijakan</span></div><div><strong>${indicators.length}</strong><span>Indikator prioritas</span></div><div><strong>12</strong><span>Sumber primer ditetapkan</span></div><div><strong>12</strong><span>Dataset terpetakan</span></div><div><strong>10</strong><span>Kontrak sumber aktif</span></div></div><div class="section-head"><div><h2>Kontrak Sumber Indikator</h2><p>Setiap indikator membawa sumber, periode, granularitas, mekanisme pembaruan, dan penanggung jawab.</p></div></div><div class="table-wrap"><table><thead><tr><th>Indikator</th><th>Kebutuhan Kebijakan</th><th>Sumber Primer</th><th>Kanal</th><th>Granularitas</th><th>Status Integrasi</th><th>Detail</th></tr></thead><tbody>${indicators.map(i=>{const c=sourceContracts[i.id],k=indicatorKnowledge[i.id];return `<tr><td><strong>${i.name}</strong><small class="table-sub">${i.opd}</small></td><td>${k.policy}</td><td>${c.primary}</td><td>${c.channel}</td><td>${c.granularity}</td><td>${badge(c.integration)}</td><td><button class="btn" data-detail="indicator:${i.id}">Buka</button></td></tr>`}).join('')}</tbody></table></div>`}
function reconciliationPage(){const cases=[{indicator:'Produksi padi',a:'BPS · statistik resmi',b:'Dinas Pertanian · administrasi sektoral',reason:'Periode panen dan metode estimasi perlu disamakan',status:'Perlu forum data'},{indicator:'Prevalensi stunting',a:'Survei resmi',b:'Pelaporan program OPD',reason:'Cakupan populasi dan metode pengukuran berbeda',status:'Perlu catatan metode'}];return `${commonHead('Rekonsiliasi Sumber','Membandingkan versi tanpa menghapus jejak, lalu mencatat alasan angka yang dipakai untuk konteks pimpinan',`<button class="btn" data-page="indicators">Buka kamus</button>`)}<section class="quality-gate"><div><span class="eyebrow">Aturan rekonsiliasi</span><h2>Perbedaan angka tidak otomatis berarti salah</h2><p>Periode, definisi, cakupan, metode, dan tingkat wilayah diperiksa lebih dulu. Sistem menyimpan semua versi dan keputusan kurasi.</p></div><ul><li><strong>Jangan dirata-rata</strong><span>Angka dari definisi berbeda tidak digabungkan.</span></li><li><strong>Utamakan kewenangan</strong><span>Sumber dipilih sesuai jenis statistik dan penggunaan.</span></li><li><strong>Catat alasan</strong><span>Pilihan nilai disertai berita acara atau catatan kurator.</span></li><li><strong>Batasi penggunaan</strong><span>Data yang belum selesai tidak masuk ringkasan produksi.</span></li></ul></section><div class="reconciliation-grid">${cases.map((item,index)=>`<article class="card reconciliation-card"><div class="card-title"><div><span class="eyebrow">Kasus 0${index+1}</span><h3>${item.indicator}</h3></div>${badge(item.status)}</div><div class="source-compare"><div><small>Versi A</small><strong>${item.a}</strong><span>Jejak sumber dipertahankan</span></div><div><small>Versi B</small><strong>${item.b}</strong><span>Jejak sumber dipertahankan</span></div></div><p><strong>Yang harus disepakati:</strong> ${item.reason}.</p><button class="btn" data-action="metric">Buka bahan rekonsiliasi</button></article>`).join('')}</div>`}
function integrationDashboard(){return `${commonHead('Kendali Integrasi','Ruang Diskominfosantik untuk menjaga koneksi, struktur, keamanan, dan jejak pertukaran data',`<button class="btn" data-page="sources">Lihat semua sumber</button><button class="btn primary" data-action="syncAll">Periksa koneksi</button>`)}<section class="coordination-hero technical-hero"><div><span class="eyebrow">Wali data & integrator</span><h2>Menghubungkan sistem tanpa mengambil alih kewenangan data OPD.</h2><p>Diskominfosantik mengelola kanal teknis, metadata, hak akses, dan pencatatan sinkronisasi. Penetapan substansi tetap pada produsen data.</p></div><div class="coordination-score readiness-score"><span>Pemetaan indikator</span><strong>12/12</strong><small>seluruh indikator prioritas memiliki sumber dan jalur pertukaran</small></div></section><div class="metrics">${metricCard('Katalog Satu Data',state.ckan.count?fmt(state.ckan.count):'Publik','Metadata dapat ditelusuri','green','⇄')}${metricCard('Kontrak Sumber',12,'Sumber primer ditetapkan','blue','◇')}${metricCard('Koneksi Aktif',10,'Diperbarui sesuai jadwal','green','✓')}${metricCard('Kanal Terbatas',2,'Keuangan dan kependudukan','red','⚿')}</div><div class="workspace-grid"><article class="card"><div class="card-title"><h3>Pekerjaan Integrasi Prioritas</h3><span>Pembaruan berjalan</span></div><div class="work-queue"><button data-page="sources"><span>01</span><div><strong>Pemetaan dataset Satu Data</strong><small>Dataset terhubung dengan 12 indikator prioritas</small></div><b>12 terpetakan</b></button><button data-page="metadata"><span>02</span><div><strong>Standarisasi metadata</strong><small>Definisi, periode, wilayah, satuan, versi, PIC</small></div><b>12/12 lengkap</b></button><button data-page="indicators"><span>03</span><div><strong>Kanal pertukaran OPD</strong><small>API, file terstruktur, atau layanan geospasial</small></div><b>6 OPD aktif</b></button></div></article><article class="card"><div class="card-title"><h3>Batas Tanggung Jawab</h3><span>Mencegah tumpang tindih</span></div><div class="responsibility-list"><div><strong>Diskominfosantik</strong><span>Koneksi, format, katalog, keamanan, log sinkronisasi.</span></div><div><strong>OPD</strong><span>Definisi, nilai, konteks, dan koreksi substansi.</span></div><div><strong>BAPPERIDA</strong><span>Kebutuhan kebijakan, rekonsiliasi, kelayakan tayang.</span></div><div><strong>Pimpinan</strong><span>Membaca ringkasan yang telah dikurasi.</span></div></div></article></div>`}
function metadataPage(){return `${commonHead('Metadata & Lineage','Jejak yang menjelaskan arti data, asal, perubahan, dan batas penggunaannya')}<div class="metrics">${metricCard('Metadata Lengkap',12,'Seluruh indikator prioritas','blue','≡')}${metricCard('Lineage Aktif',10,'Jejak pembaruan tersedia','green','⇄')}${metricCard('Granularitas Wilayah',3,'Data tersedia hingga kecamatan','green','⌖')}${metricCard('PIC Terkonfirmasi',10,'Penanggung jawab tercatat','blue','✓')}</div><div class="table-wrap"><table><thead><tr><th>Indikator</th><th>Definisi</th><th>Sumber Primer</th><th>Periode/Frekuensi</th><th>Wilayah</th><th>Status Lineage</th></tr></thead><tbody>${indicators.map(i=>`<tr><td><strong>${i.name}</strong></td><td>${indicatorKnowledge[i.id].definition}</td><td>${sourceContracts[i.id].primary}</td><td>${i.period}</td><td>${sourceContracts[i.id].granularity}</td><td>${badge('Tercatat')}</td></tr>`).join('')}</tbody></table></div>`}
function opdInboxPage(){const items=validations.filter(v=>v.opd==='Dinas Kesehatan'||v.opd.includes('PUPR')).slice(0,3);return `${commonHead('Kotak Konfirmasi Data','Ruang OPD untuk memeriksa substansi tanpa mengunggah ulang data yang sudah tersedia',`<button class="btn" data-page="indicators">Lihat tanggung jawab indikator</button>`)}<section class="integration-policy"><div><strong>Tidak membuat silo baru</strong><p>SABABUKA merujuk Satu Data, BPS, atau sistem OPD. OPD mengonfirmasi nilai, definisi, periode, dan catatan.</p></div><div><strong>Unggah hanya sebagai pengecualian</strong><p>Berkas manual digunakan jika belum ada kanal resmi dan dicatat dalam riwayat pertukaran data.</p></div></section><div class="metrics">${metricCard('Perlu Konfirmasi',items.length,'Antrean Dinas Kesehatan/DPUPRPKP','amber','◴')}${metricCard('Perlu Koreksi',1,'Catatan dikembalikan ke kurator','red','↩')}${metricCard('Sudah Dikonfirmasi',8,'Tercatat dalam riwayat','green','✓')}${metricCard('Unggah Ulang Wajib',0,'Gunakan sumber yang sudah ada','blue','⇄')}</div><div class="section-head"><div><h2>Antrean Pemeriksaan Substansi</h2><p>Periksa definisi, periode, nilai, cakupan, dan catatan sebelum data diteruskan.</p></div></div><div class="table-wrap"><table><thead><tr><th>Indikator</th><th>Nilai Terbaru</th><th>Sumber yang Dirujuk</th><th>Yang Diperiksa OPD</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${items.map(v=>`<tr><td><strong>${v.indicator}</strong></td><td>${v.latest}</td><td>${v.source}</td><td>Definisi, periode, nilai, cakupan, dan catatan</td><td>${badge('Menunggu konfirmasi')}</td><td><button class="btn" data-action="metric">Periksa</button></td></tr>`).join('')}</tbody></table></div>`}
function meetingFinance(){
  const guide=`<section class="quality-gate"><div><span class="eyebrow">Kendali data keuangan</span><h2>Ringkasan keuangan menggunakan agregat resmi sesuai periode pelaporan</h2><p>Data dibaca dari BPKAD dan Bapenda melalui akses terotorisasi, dengan cut-off serta pengesahan yang dapat ditelusuri.</p></div><ul><li><strong>Sumber data</strong><span>BPKAD, Bapenda, dan sistem keuangan resmi daerah.</span></li><li><strong>Basis realisasi</strong><span>Definisi pencatatan dan cut-off ditampilkan pada setiap laporan.</span></li><li><strong>Hak akses</strong><span>Informasi internal, pimpinan, dan publik dikelola secara berjenjang.</span></li><li><strong>Jejak pembaruan</strong><span>Waktu pembaruan dan penanggung jawab data tercatat.</span></li></ul></section>`;
  let html=financePage().replace('Ringkasan pendapatan, belanja, dan penyerapan APBD','Posisi pendapatan, belanja, penyerapan, serta perbandingan terhadap target periode');
  html=html.replace('</div><div class="finance-grid">',`</div>${guide}<div class="finance-grid">`);
  return html;
}
function meetingServices(){
  const guide=`<section class="quality-gate"><div><span class="eyebrow">Kendali pelayanan publik</span><h2>Kinerja layanan dibaca dari volume, waktu, kepuasan, dan pengaduan</h2><p>SABABUKA menggunakan data agregat dari sistem pengampu layanan. Data individu dan status permohonan warga tidak disalin.</p></div><ul><li><strong>Cakupan layanan</strong><span>Ditetapkan bersama Disdukcapil dan OPD penyelenggara layanan.</span></li><li><strong>Definisi selesai</strong><span>Mengikuti proses bisnis resmi tiap layanan.</span></li><li><strong>Standar waktu</strong><span>Diukur terhadap SLA yang telah ditetapkan.</span></li><li><strong>Kepuasan</strong><span>Instrumen, periode, dan jumlah responden dapat ditelusuri.</span></li></ul></section>`;
  let html=servicesPage().replace('Volume, kecepatan penyelesaian, kepuasan dan isu layanan','Volume, ketepatan waktu penyelesaian, kepuasan masyarakat, dan tindak lanjut pengaduan');
  return html.replace('</div><div class="service-grid">',`</div>${guide}<div class="service-grid">`);
}
function commonHead(title,desc,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div><div class="filterbar">${actions}</div></div>`}
function mapPage(){const d=districts.find(x=>x.name===state.district),metric=mapIndicator(),selectedValue=metric.value(d),level=metric.level(selectedValue),sorted=[...districts].sort((a,b)=>metric.value(b)-metric.value(a));return `${commonHead('Profil Wilayah & Peta Indikator','Peta tematik 17 kecamatan untuk membaca kesenjangan wilayah berdasarkan indikator terpilih',`<select class="select" id="indicatorSelect" aria-label="Pilih indikator peta">${Object.entries(mapIndicators).map(([key,item])=>`<option value="${key}" ${state.mapIndicator===key?'selected':''}>${item.label}</option>`).join('')}</select><select class="select"><option>${state.year}</option></select>`)}<section class="integration-policy"><div><strong>Perbandingan antarkecamatan</strong><p>Warna wilayah mengikuti kondisi indikator yang dipilih. Klik kecamatan untuk membuka nilai, periode, dan data pendukungnya.</p></div><div><strong>Ketepatan granularitas</strong><p>Data kecamatan hanya ditampilkan ketika sumber tersedia pada tingkat wilayah tersebut; angka kabupaten tidak diturunkan secara asumtif.</p></div></section><div class="map-layout"><div class="card map-card"><div class="card-title"><div><h3>Peta Kabupaten Kapuas</h3><span>${metric.label} · 17 kecamatan</span></div><span class="data-seal verified">DATA WILAYAH TERVERIFIKASI</span></div>${geographicMap()}</div><div class="card district-profile"><div class="card-title"><div><span class="eyebrow">Wilayah terpilih</span><h3>${d.name}</h3></div>${badge(level==='good'?'Baik':level==='attention'?'Perlu Perhatian':'Prioritas')}</div><div class="selected-metric"><span>${metric.label}</span><strong>${fmt(selectedValue)} <small>${metric.unit}</small></strong><p>Warna wilayah mengikuti ambang indikator yang berlaku pada periode ini.</p></div><div class="district-facts"><div><span>Kemiskinan</span><strong>${d.poverty}%</strong></div><div><span>Stunting</span><strong>${d.stunting}%</strong></div><div><span>Jalan Mantap</span><strong>${d.roads}%</strong></div></div><button class="btn" data-detail="district:${encodeURIComponent(d.name)}">Buka profil wilayah</button></div></div><div class="two-col"><div class="card"><div class="card-title"><h3>Sebaran Nilai Kecamatan</h3><span>${metric.label}</span></div><div class="rank-list">${sorted.slice(0,9).map(x=>{const value=metric.value(x);return `<div class="rank-row"><i class="mini-dot" style="background:${mapColor(metric.level(value))}"></i><strong>${x.name}</strong><div class="htrack"><div class="hfill" style="width:${Math.min(100,value)}%"></div></div><strong>${fmt(value)} ${metric.unit}</strong></div>`}).join('')}</div></div><div class="card"><div class="card-title"><h3>Tabel Seluruh Kecamatan</h3><span>Klik baris untuk melihat profil</span></div><div class="table-wrap" style="max-height:360px"><table><thead><tr><th>Kecamatan</th><th>Indeks</th><th>Kemiskinan</th><th>Stunting</th><th>Jalan</th></tr></thead><tbody>${districts.map(x=>`<tr data-district="${x.name}" style="cursor:pointer"><td><strong>${x.name}</strong></td><td>${x.score}</td><td>${x.poverty}%</td><td>${x.stunting}%</td><td>${x.roads}%</td></tr>`).join('')}</tbody></table></div></div></div>`}
const clampScore=value=>Math.max(0,Math.min(100,Math.round(value)));
function opdDimensions(o){const progress=+(o.score/o.target*100).toFixed(1),gap=+(o.score-o.target).toFixed(1),status=progress>=100?'Tercapai':progress>=95?'Dalam Jalur':'Perlu Tindak Lanjut';return {achievement:o.score,target:o.target,progress,gap,status}}
function opdPage(){const rows=opds.map(o=>Object.assign(o,{status:opdDimensions(o).status})),filtered=rows.filter(o=>(state.status==='Semua'||o.status===state.status)&&(state.search===''||o.name.toLowerCase().includes(state.search.toLowerCase()))),achieved=rows.filter(o=>o.status==='Tercapai').length,onTrack=rows.filter(o=>o.status==='Dalam Jalur').length;return `${commonHead('Capaian Target OPD','Pemantauan realisasi setiap perangkat daerah terhadap target kerjanya sendiri—tanpa ranking antar-OPD',`<input class="search" id="opdSearch" value="${state.search}" placeholder="Cari OPD"><select class="select" id="statusFilter"><option ${state.status==='Semua'?'selected':''}>Semua</option><option ${state.status==='Tercapai'?'selected':''}>Tercapai</option><option ${state.status==='Dalam Jalur'?'selected':''}>Dalam Jalur</option><option ${state.status==='Perlu Tindak Lanjut'?'selected':''}>Perlu Tindak Lanjut</option></select><button class="btn" data-action="reset">Reset</button>`)}<section class="quality-gate target-gate"><div><span class="eyebrow">Prinsip pembacaan</span><h2>Setiap OPD dibandingkan dengan target kerja yang disepakati</h2><p>Tampilan ini tidak membuat peringkat antar-OPD. Perbedaan mandat, jenis layanan, kapasitas, serta jadwal program tetap dihormati.</p></div><ul><li><strong>Dasar pembanding</strong><span>Realisasi periode berjalan dibandingkan dengan target OPD pada periode yang sama.</span></li><li><strong>Status Tercapai</strong><span>Realisasi sama dengan atau melampaui targetnya sendiri.</span></li><li><strong>Status Dalam Jalur</strong><span>Progres minimal 95% dan masih dapat dikejar pada periode berjalan.</span></li><li><strong>Perlu Tindak Lanjut</strong><span>Forum digunakan untuk membuka hambatan dan dukungan, bukan memberi stigma.</span></li></ul></section><div class="metrics">${metricCard('OPD Terpantau',rows.length,'Perangkat daerah pada tahap awal','blue','◫')}${metricCard('Target Tercapai',achieved,'Terhadap target masing-masing','green','✓')}${metricCard('Dalam Jalur',onTrack,'Masih sesuai lintasan periode','amber','↗')}${metricCard('Perlu Tindak Lanjut',rows.length-achieved-onTrack,'Fokus dukungan dan koordinasi','red','!')}</div><div class="section-head"><div><h2>Capaian terhadap Target Masing-Masing</h2><p>Nilai target pada paparan awal perlu dikonfirmasi dan disepakati bersama pemilik data.</p></div></div>${filtered.length?`<div class="table-wrap"><table><thead><tr><th>OPD</th><th>Indikator Terpantau</th><th>Realisasi</th><th>Target OPD</th><th>Selisih</th><th>Progres</th><th>Status</th><th>Pembaruan</th><th>Aksi</th></tr></thead><tbody>${filtered.map(o=>{const d=opdDimensions(o);return `<tr><td><strong>${o.name}</strong></td><td>${o.count}</td><td>${fmt(d.achievement)}%</td><td>${fmt(d.target)}%</td><td class="${d.gap>=0?'trend-up':'trend-down'}">${d.gap>=0?'+':''}${fmt(d.gap)} poin</td><td><div class="target-progress"><span style="width:${Math.min(100,d.progress)}%"></span></div><small>${fmt(d.progress)}%</small></td><td>${badge(d.status)}</td><td>${o.updated}</td><td><button class="btn" data-detail="opd:${o.id}">Detail</button></td></tr>`}).join('')}</tbody></table></div>`:`<div class="card empty"><div class="big">⌕</div><strong>Tidak ada OPD yang sesuai filter</strong><p>Ubah filter atau reset pencarian.</p></div>`}`}
function financePage(){return `${commonHead('Keuangan Daerah','Ringkasan pendapatan, belanja, dan penyerapan APBD',`<button class="btn" data-action="export">⇩ Ekspor Ringkasan</button>`)}<div class="finance-grid">${metricCard('Pendapatan Daerah','Rp1,42 T','Target berjalan Rp1,36 T','green','↗')}${metricCard('Belanja Daerah','Rp1,36 T','Dari pagu Rp2,31 T','blue','▤')}${metricCard('Penyerapan Anggaran','58,7%','Target periode 60,0%','amber','◴')}${metricCard('Selisih terhadap Target','-1,3 pt','Perlu akselerasi Agustus–September','red','!')}</div><div class="two-col"><div class="card"><div class="card-title"><h3>Target vs Realisasi Bulanan</h3><span>Persen penyerapan</span></div><div class="chart">${finance.monthly.map((v,i)=>`<div class="bar-col"><div class="bar" style="height:${v/70*100}%" data-tip="Realisasi ${v}%"></div><div class="bar target" style="height:${(45+i*4)/70*100}%" data-tip="Target ${45+i*4}%"></div><span class="axis-label">${['Mar','Apr','Mei','Jun','Jul','Agu'][i]}</span></div>`).join('')}</div></div><div class="card"><div class="card-title"><h3>Komposisi Belanja</h3></div><div class="hbars">${finance.composition.map(x=>`<div class="hrow"><span>${x[0]}</span><div class="htrack"><div class="hfill" style="width:${x[1]}%"></div></div><strong>${x[1]}%</strong></div>`).join('')}</div></div></div><div class="section-head"><div><h2>Ringkasan Perangkat Daerah</h2></div></div><div class="table-wrap"><table><thead><tr><th>Perangkat Daerah</th><th>Pagu</th><th>Realisasi</th><th>Penyerapan</th><th>Status</th></tr></thead><tbody>${opds.slice(0,9).map((o,i)=>`<tr><td><strong>${o.name}</strong></td><td>Rp${[186,244,315,428,168,237,152,133,96][i]} M</td><td>Rp${Math.round([186,244,315,428,168,237,152,133,96][i]*o.score/100*.72)} M</td><td>${Math.round(o.score*.72)}%</td><td>${badge(o.score>86?'Baik':o.score>78?'Perlu Perhatian':'Kritis')}</td></tr>`).join('')}</tbody></table></div>`}
function servicesPage(){const total=services.reduce((s,x)=>s+x.volume,0),done=services.reduce((s,x)=>s+x.done,0);return `${commonHead('Pelayanan Publik','Volume, kecepatan penyelesaian, kepuasan dan isu layanan') }<div class="service-grid">${metricCard('Jumlah Layanan',total.toLocaleString('id-ID'),'6 kelompok layanan','blue','◎')}${metricCard('Permohonan Selesai',done.toLocaleString('id-ID'),`${Math.round(done/total*100)}% dari permohonan`,'green','✓')}${metricCard('Rata-rata Penyelesaian','2,7 hari','Lebih cepat 0,3 hari','green','◴')}${metricCard('Pengaduan Terbuka','87','12 membutuhkan tindak lanjut','amber','!')}</div><div class="two-col"><div class="card"><div class="card-title"><h3>Tren Volume Layanan</h3><span>Mar–Agu 2026</span></div><div class="chart">${[62,68,73,78,84,91].map((v,i)=>`<div class="bar-col"><div class="bar" style="height:${v}%" data-tip="${['Mar','Apr','Mei','Jun','Jul','Agu'][i]}: ${v*820}"></div><span class="axis-label">${['Mar','Apr','Mei','Jun','Jul','Agu'][i]}</span></div>`).join('')}</div></div><div class="card"><div class="card-title"><h3>Kepuasan menurut Kategori</h3></div><div class="hbars">${services.map(x=>`<div class="hrow"><span>${x.name.split(' ')[0]}</span><div class="htrack"><div class="hfill" style="width:${x.satisfaction}%"></div></div><strong>${x.satisfaction}</strong></div>`).join('')}</div></div></div><div class="section-head"><div><h2>Layanan dengan Volume Tertinggi</h2></div></div><div class="table-wrap"><table><thead><tr><th>Layanan</th><th>Volume</th><th>Selesai</th><th>Rata-rata Waktu</th><th>Kepuasan</th><th>Status</th></tr></thead><tbody>${services.map(s=>`<tr><td><strong>${s.name}</strong></td><td>${s.volume.toLocaleString('id-ID')}</td><td>${s.done.toLocaleString('id-ID')}</td><td>${s.time} hari</td><td>${s.satisfaction}</td><td>${badge(s.satisfaction>=88?'Baik':s.satisfaction>=85?'Perlu Perhatian':'Kritis')}</td></tr>`).join('')}</tbody></table></div>`}
function analysisPageBase(){return `${commonHead('Analisis dan Rekomendasi','Temuan sistem untuk bahan pertimbangan pimpinan',`<select class="select"><option>Semua Fokus</option><option>Ketahanan Pangan</option><option>Infrastruktur</option><option>Kesehatan</option><option>Kemiskinan</option><option>Ekonomi</option><option>Kebencanaan</option></select><select class="select"><option>Semua Urgensi</option><option>Kritis</option><option>Tinggi</option></select><button class="btn" data-action="reset">Reset</button>`)}<section class="analysis-brief"><div class="analysis-lead"><div class="brief-kicker">Brief pimpinan · 28 Agustus 2026</div><h2>Empat fokus memerlukan keputusan; empat fokus lain tetap dalam pemantauan strategis.</h2><p>Cetak sawah dan irigasi, konektivitas, stunting, serta ketepatan sasaran DTSEN membutuhkan penyelarasan lintas OPD. Inflasi, bencana, pendidikan, dan integrasi digital dipantau melalui ambang yang disepakati.</p><div class="brief-signal"><span>4 <small>fokus pimpinan</small></span><span>4 <small>pantauan strategis</small></span><span>8 <small>isu lintas OPD</small></span></div></div><aside class="decision-note"><span class="decision-label">Keputusan yang dibutuhkan</span><strong>Satukan target, wilayah, pengampu, dan kebutuhan dukungan dalam satu forum pimpinan.</strong><p>Setiap OPD tetap dinilai terhadap targetnya sendiri; matriks isu hanya menunjukkan peran lintas sektor.</p><button class="btn primary" data-page="alerts">Buka Pusat Peringatan</button></aside></section><section class="analysis-focus"><div class="focus-heading"><span class="focus-index">01</span><div><div class="eyebrow">Lokasi yang perlu didahulukan</div><h3>Tiga wilayah membentuk kantong risiko layanan dasar</h3></div></div><div class="territory-strip"><div><span>Mandau Talawang</span><strong>61</strong><small>Stunting 28% · Jalan 49%</small></div><div><span>Pasak Talawang</span><strong>63</strong><small>Stunting 27% · Jalan 52%</small></div><div><span>Kapuas Hulu</span><strong>64</strong><small>Stunting 26% · Jalan 55%</small></div></div><p class="focus-summary">Pola yang berulang menunjukkan kebutuhan intervensi terpadu, bukan program sektoral yang berjalan sendiri-sendiri.</p></section><section class="intervention-board"><div class="focus-heading"><span class="focus-index">02</span><div><div class="eyebrow">Celah terhadap target 2026</div><h3>Empat fokus utama dan pemilik tindak lanjut</h3></div></div>${strategicIssues.filter(item=>item.group==='Prioritas Pimpinan').map((item,index)=>`<div class="intervention-row"><div class="intervention-name"><span class="risk-dot ${item.status==='Kritis'?'red-dot':index===3?'gold-dot':'amber-dot'}"></span><strong>${item.title}</strong><small>${item.lead}</small></div><div class="intervention-progress"><span style="width:${[42,68,78,86][index]}%"></span></div><div class="intervention-value"><strong>${item.value}</strong><small>${item.target}</small></div><p>${item.decision}.</p></div>`).join('')}</section><section class="action-runway"><div class="runway-intro"><div class="eyebrow">Arah kerja berikutnya</div><h3>Satu pekan untuk mengubah temuan menjadi keputusan</h3><p>Urutan kerja dibuat berdasarkan ketergantungan data, program, dan wilayah.</p></div><div class="runway-step"><time>Hari 1–2</time><strong>Pastikan angka</strong><p>Verifikasi target, realisasi, periode, wilayah, dan sumber pada empat fokus utama.</p></div><div class="runway-step"><time>Hari 3–4</time><strong>Uji rencana OPD</strong><p>Bandingkan percepatan program dengan target dan kapasitas pelaksanaan.</p></div><div class="runway-step"><time>Hari 5–7</time><strong>Putuskan dukungan</strong><p>Sepakati pengampu, OPD pendukung, fokus wilayah, tenggat, dan mekanisme pemantauan.</p></div></section>`}
function analysisPage(){return analysisPageBase()+strategicIssueMatrix()}
function alertsPage(){return `${commonHead('Pusat Peringatan','Deteksi dini, validasi BAPPERIDA, konfirmasi OPD, dan eskalasi isu kepada pimpinan',`<select class="select"><option>Semua Urgensi</option><option>Kritis</option><option>Tinggi</option><option>Sedang</option></select><select class="select"><option>Semua Status</option><option>Baru</option><option>Ditinjau</option><option>Selesai</option></select>`)}<section class="verification-flow"><div class="done"><span>01</span><strong>Deteksi</strong><small>Perubahan indikator, keterlambatan, atau anomali</small></div><div class="active"><span>02</span><strong>Validasi BAPPERIDA</strong><small>Periksa sumber, konteks, dan urgensi</small></div><div><span>03</span><strong>Konfirmasi OPD</strong><small>Produsen data memberi penjelasan dan tindak lanjut</small></div><div><span>04</span><strong>Eskalasi Pimpinan</strong><small>Hanya isu tervalidasi masuk ke Ringkasan Pimpinan</small></div></section><div class="metrics">${metricCard('Menunggu Validasi',alerts.filter(a=>a.status==='Baru').length,'Antrean BAPPERIDA','red','!')}${metricCard('Telah Ditinjau',alerts.filter(a=>a.status==='Ditinjau').length,'Siap dikonfirmasi atau dieskalasikan','amber','▲')}${metricCard('Dalam Pemantauan',alerts.filter(a=>a.urgency==='Sedang').length,'Perlu pembaruan berkala','blue','●')}${metricCard('Selesai',alerts.filter(a=>a.status==='Selesai').length,'Tindak lanjut telah ditutup','green','✓')}</div><div class="section-head"><div><h2>Antrean Peringatan BAPPERIDA</h2><p>Peringatan baru tidak langsung muncul pada Ringkasan Pimpinan sebelum melalui validasi.</p></div></div>${alertsList(20)}`}
function sourcesPageLegacy(){return `${commonHead('Sumber Data','Registry sumber resmi, jalur integrasi, dan status kesiapan',`<button class="btn" data-action="syncAll">↻ Periksa Katalog</button>`)}<div class="metrics">${metricCard('Katalog Satu Data',state.ckan.status==='siap'?'Aktif':'Diperiksa',state.ckan.count?`${fmt(state.ckan.count)} dataset terindeks`:'CKAN API publik','green','⇄')}${metricCard('Rujukan Publik BPS','Aktif','Domain Kabupaten Kapuas 6203','green','BPS')}${metricCard('Sumber OPD Terdaftar',opdSourceRegistry.length,'Enam bidang prioritas','blue','▤')}${metricCard('Kanal Akses Terbatas',2,'Pendapatan dan kependudukan','red','⚿')}</div><section class="integration-policy"><div><strong>Prinsip integrasi</strong><p>SABABUKA tidak mengambil angka dari halaman berita. Data indikator masuk melalui API, CSV/XLSX terstruktur, layanan geospasial, atau pertukaran data yang disetujui.</p></div><div><strong>Perlindungan data</strong><p>Data individu, transaksi, serta status pelayanan warga tidak masuk ke dashboard publik. Sistem menggunakan agregat sesuai kewenangan.</p></div></section><div class="section-head"><div><h2>OPD Prioritas</h2><p>Status kanal integrasi dan pembaruan sumber</p></div></div><div class="table-wrap"><table><thead><tr><th>OPD</th><th>Bidang Data</th><th>Jalur Integrasi</th><th>Status</th><th>Catatan Integrasi</th><th>Website Resmi</th></tr></thead><tbody>${opdSourceRegistry.map(s=>`<tr><td><strong>${s.name}</strong></td><td>${s.sector}</td><td>${s.channel}</td><td>${badge(s.status)}</td><td class="source-note">${s.note}</td><td><a class="source-link" href="${s.url}" target="_blank" rel="noopener">Buka sumber</a></td></tr>`).join('')}</tbody></table></div><div class="section-head"><div><h2>Sumber Data Internal</h2><p>Jadwal dan status sinkronisasi</p></div></div><div class="table-wrap"><table><thead><tr><th>Nama Sumber</th><th>OPD Pemilik</th><th>Jenis</th><th>Jadwal</th><th>Dataset</th><th>Status</th></tr></thead><tbody>${sources.map(s=>`<tr><td><strong>${s.name}</strong></td><td>${s.owner}</td><td>${s.type}</td><td>${s.schedule}</td><td>${s.datasets}</td><td>${badge('Aktif')}</td></tr>`).join('')}</tbody></table></div>`}
function bpsRegistryPanel(){return `<section class="bps-registry"><div class="bps-registry-head"><div class="channel-mark">BPS</div><div><span class="eyebrow">Integrasi sumber statistik resmi</span><h2>BPS Kabupaten Kapuas</h2><p>Sumber publik resmi telah dipasang sebagai rujukan provenance. Pengambilan nilai otomatis melalui WebAPI BPS disiapkan untuk domain 6203 dan memerlukan token aplikasi di backend.</p></div><span class="badge good">RUJUKAN AKTIF</span></div><div class="bps-resource-grid">${state.bps.items.map(item=>`<a href="${item.url}" target="_blank" rel="noopener"><small>${item.type}</small><strong>${item.title}</strong><span>Buka sumber resmi ↗</span></a>`).join('')}<a href="https://webapi.bps.go.id/developer" target="_blank" rel="noopener"><small>Integrasi mesin</small><strong>WebAPI BPS</strong><span>Dokumentasi API resmi ↗</span></a></div><div class="api-readiness"><strong>Status teknis:</strong> katalog publik dan tautan provenance aktif; konektor nilai otomatis menunggu token WebAPI BPS yang disimpan aman di backend, bukan di browser.</div></section>`}
function sourcesPage(){return sourcesPageLegacy().replace('<div class="metrics">',`${bpsRegistryPanel()}<div class="metrics">`)}
function validationPage(){const waiting=validations.filter(v=>v.status==='Menunggu').length,reviewing=validations.filter(v=>v.status==='Diperiksa').length,approved=validations.filter(v=>v.status==='Disetujui').length,returned=validations.filter(v=>v.status==='Perbaikan').length;return `${commonHead('Kurasi & Kelayakan Tayang','Ruang BAPPERIDA untuk memeriksa konteks kebijakan setelah substansi OPD dan struktur teknis tersedia',`<button class="btn" data-page="reconciliation">Buka rekonsiliasi</button><button class="btn primary" data-page="summary">Ringkasan Pimpinan</button>`)}<section class="verification-flow"><div class="done"><span>01</span><strong>Pemeriksaan teknis</strong><small>Diskominfosantik: koneksi dan metadata</small></div><div class="active"><span>02</span><strong>Konfirmasi OPD</strong><small>Nilai, definisi, periode, konteks</small></div><div><span>03</span><strong>Kurasi BAPPERIDA</strong><small>Rekonsiliasi dan batas penggunaan</small></div><div><span>04</span><strong>Layak tayang</strong><small>Masuk ringkasan pimpinan</small></div></section><div class="metrics">${metricCard('Menunggu Konfirmasi',waiting,'Produsen data perlu memeriksa','amber','◴')}${metricCard('Sedang Dikurasi',reviewing,'Pemeriksaan substansi aktif','blue','⌕')}${metricCard('Layak Tayang',approved,'Masuk ringkasan pimpinan','green','✓')}${metricCard('Minta Perbaikan',returned,'Kembali ke pemilik substansi','red','↩')}</div><section class="quality-gate"><div><span class="eyebrow">Aturan kelayakan tayang</span><h2>Empat syarat sebelum data disajikan kepada pimpinan</h2></div><ul><li><strong>Sumber berwenang</strong><span>Statistik resmi, Satu Data, atau produsen data sektoral.</span></li><li><strong>Substansi dikonfirmasi</strong><span>OPD memastikan nilai, definisi, periode, dan konteks.</span></li><li><strong>Perbedaan selesai</strong><span>Versi sumber direkonsiliasi tanpa menghapus jejak.</span></li><li><strong>Batas penggunaan jelas</strong><span>Granularitas, kualitas, dan risiko salah tafsir dicatat.</span></li></ul></section><div class="section-head"><div><h2>Antrean Kurasi</h2><p>Setiap keputusan kurasi tercatat dan menentukan kelayakan data pada ringkasan pimpinan.</p></div></div><div class="table-wrap"><table><thead><tr><th>Indikator</th><th>Produsen Data</th><th>Sebelumnya</th><th>Nilai Terbaru</th><th>Perubahan</th><th>Rujukan</th><th>Tanggal Masuk</th><th>Tahap</th><th>Aksi</th></tr></thead><tbody>${validations.map(v=>`<tr><td><strong>${v.indicator}</strong></td><td>${v.opd}</td><td>${v.prev}</td><td>${v.latest}</td><td>${v.change}</td><td>${v.source}</td><td>${v.date}</td><td>${badge(v.status)}</td><td><button class="btn" data-detail="validation:${v.id}">${v.status==='Disetujui'?'Lihat jejak':'Periksa'}</button></td></tr>`).join('')}</tbody></table></div>`}
function settingsPage(){return `${commonHead('Pengaturan','Preferensi tampilan untuk sesi presentasi') }<div class="card" style="max-width:760px"><div class="card-title"><h3>Preferensi Dashboard</h3></div><div class="indicator-row" style="padding:14px 0;border-bottom:1px solid var(--line)"><div><strong>Mode Presentasi</strong><div class="topbar-meta">Memperluas area konten dan menyederhanakan elemen administratif.</div></div><button class="btn" id="presentationBtn2">${state.presentation?'Nonaktifkan':'Aktifkan'}</button></div><div class="indicator-row" style="padding:14px 0;border-bottom:1px solid var(--line)"><div><strong>Tahun Aktif</strong><div class="topbar-meta">Periode utama dashboard.</div></div><select class="select" id="yearSelect2">${years.map(y=>`<option ${y===state.year?'selected':''}>${y}</option>`).join('')}</select></div><div class="indicator-row" style="padding:14px 0"><div><strong>Reset Pengaturan Tampilan</strong><div class="topbar-meta">Mengembalikan sidebar dan filter ke kondisi awal.</div></div><button class="btn" data-action="resetAll">Reset</button></div></div>`}
const escapeHtml=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
function findStrategicIssue(q){const aliases={food:['pangan','cetak sawah','irigasi','pertanian'],infrastructure:['infrastruktur','jalan','jembatan','konektivitas'],stunting:['stunting','sanitasi','kesehatan'],poverty:['kemiskinan','dtsen','bansos'],inflation:['inflasi','harga pangan','daya beli'],disaster:['banjir','karhutla','bencana'],education:['pendidikan','sekolah rakyat'],digital:['digital','integrasi','pelayanan']};return strategicIssues.find(item=>(aliases[item.id]||[]).some(term=>q.includes(term)))}
function chatbotReply(question){const q=question.toLowerCase(),critical=indicators.filter(i=>i.status==='critical'),priority=[...districts].sort((a,b)=>a.score-b.score).slice(0,3),indicator=indicators.find(i=>q.includes(i.name.toLowerCase().split(' ')[0])||q.includes(i.id)),issue=findStrategicIssue(q);if(q.includes('ringkas')||q.includes('kondisi daerah'))return `Empat fokus masuk layar keputusan pimpinan: ${strategicIssues.filter(item=>item.group==='Prioritas Pimpinan').map(item=>item.title).join(', ')}. Empat fokus lain tetap dipantau dan dapat dinaikkan ketika melewati ambang. Data yang menunggu konfirmasi tidak digunakan sebagai kesimpulan final.`;if(q.includes('stunting')||q.includes('tren kesehatan')){const i=indicators.find(x=>x.id==='stunting');return `Prevalensi stunting: ${i.trend.map((v,index)=>`${years[index]} ${fmt(v)}%`).join(' · ')}. Nilai ${state.year} sebesar ${fmt(i.value)}%, atau ${fmt(i.value-i.target)} poin di atas target ${fmt(i.target)}%. Sumber pada sistem: ${i.opd}, periode ${i.period}.`};if(issue)return `${issue.title} berada pada kelompok ${issue.group}. Parameter yang tampil: ${issue.metric} ${issue.value} (${issue.target}), status ${issue.status}. Pengampu: ${issue.lead}. Pendukung: ${issue.support}. Kebutuhan tindak lanjut: ${issue.decision}.`;if(q.includes('kritis')||q.includes('perhatian'))return `${critical.length} indikator berstatus kritis: ${critical.map(i=>`${i.name} (${fmt(i.value)} ${i.unit}; target ${fmt(i.target)} ${i.unit})`).join(', ')}. Pemilik data yang tercatat: ${[...new Set(critical.map(i=>i.opd))].join(', ')}.`;if(q.includes('kecamatan')||q.includes('wilayah'))return `Berdasarkan indeks wilayah yang tersedia, tiga nilai terendah adalah ${priority.map(d=>`${d.name} (${d.score})`).join(', ')}. Data pendukung yang tercatat mencakup kemiskinan, stunting, dan jalan mantap.`;if(q.includes('opd')||q.includes('kinerja')){const status=opds.map(opdDimensions);return `${opds.length} OPD terpantau terhadap targetnya masing-masing: ${status.filter(item=>item.status==='Tercapai').length} tercapai, ${status.filter(item=>item.status==='Dalam Jalur').length} dalam jalur, dan ${status.filter(item=>item.status==='Perlu Tindak Lanjut').length} perlu tindak lanjut. Tidak ada ranking antar-OPD.`};if(q.includes('anggaran')||q.includes('keuangan'))return `Penyerapan anggaran periode Agustus ${state.year} tercatat ${fmt(finance.absorption)}%, atau ${fmt(60-finance.absorption)} poin di bawah target periode 60%. Pola bulanan yang tersedia: ${finance.monthly.map((v,i)=>`${['Mar','Apr','Mei','Jun','Jul','Agu'][i]} ${fmt(v)}%`).join(' · ')}.`;if(indicator)return `${indicator.name} tercatat ${fmt(indicator.value)} ${indicator.unit}, target ${fmt(indicator.target)} ${indicator.unit}, dan status ${statusLabel(indicator.status)}. Tren yang tersedia: ${indicator.trend.map((v,index)=>`${years[index]} ${fmt(v)}`).join(' · ')}. Sumber pada sistem: ${indicator.opd}, periode ${indicator.period}.`;return 'Informasi tersebut belum tersedia pada data SABABUKA yang sedang dimuat. Saya tidak akan membuat asumsi. Silakan tanyakan fokus pangan, infrastruktur, stunting, DTSEN, inflasi, bencana, pendidikan, integrasi digital, wilayah, OPD, atau keuangan.'}
function formatAssistantMessage(text){const sentences=String(text).trim().replace(/\.$/,'').split(/\.\s+/).filter(Boolean),first=sentences.shift()||'',colon=first.indexOf(':'),hasTitle=colon>0&&colon<72,title=hasTitle?first.slice(0,colon):'Ringkasan Jawaban',lead=hasTitle?first.slice(colon+1).trim():first;const valueBlock=value=>{const parts=value.split(' · ').map(part=>part.trim()).filter(Boolean);return parts.length>1?`<div class="chat-answer-chips">${parts.map(part=>`<span>${escapeHtml(part)}</span>`).join('')}</div>`:`<div class="chat-answer-lead">${escapeHtml(value)}</div>`};const details=sentences.map(sentence=>{const cut=sentence.indexOf(':');if(cut>0&&cut<48)return `<div class="chat-answer-row"><span>${escapeHtml(sentence.slice(0,cut))}</span><strong>${escapeHtml(sentence.slice(cut+1).trim())}</strong></div>`;return `<div class="chat-answer-point"><i></i><span>${escapeHtml(sentence)}</span></div>`}).join('');return `<div class="chat-answer"><div class="chat-answer-title"><span>✦</span><strong>${escapeHtml(title)}</strong></div>${valueBlock(lead)}${details?`<div class="chat-answer-details">${details}</div>`:''}</div>`}
function assistantPage(){const prompts=['Ringkas kondisi daerah','Bagaimana progres cetak sawah?','Apa status DTSEN?','Bagaimana tren stunting?','Apa pantauan banjir dan karhutla?','Bagaimana kinerja OPD?'];return `${commonHead('Asisten Data','Navigasi percakapan untuk menelusuri indikator, wilayah, sumber, dan tindak lanjut',`<span class="badge good">DATA TERKURASI</span>`)}<div class="chat-layout"><aside class="chat-context"><div class="chat-context-head"><span class="chat-logo">S</span><div><strong>Ruang lingkup jawaban</strong><small>Data tersedia 2022–2026</small></div></div><dl><div><dt>${strategicIssues.length}</dt><dd>fokus lintas OPD</dd></div><div><dt>${districts.length}</dt><dd>kecamatan</dd></div><div><dt>${opds.length}</dt><dd>OPD terpantau</dd></div><div><dt>${indicators.length}</dt><dd>indikator strategis</dd></div></dl><p>Asisten hanya menggunakan data dan metadata yang tersedia di SABABUKA. Pertanyaan di luar cakupan akan dijawab sebagai data belum tersedia tanpa membuat asumsi.</p><div class="chat-suggestions">${prompts.map(p=>`<button type="button" data-chat-prompt="${p}">${p}</button>`).join('')}</div></aside><section class="chat-panel" aria-label="Percakapan Asisten Data"><div class="chat-header"><div><strong>Asisten Data SABABUKA</strong><span><i></i> Siap membaca data dan jejak sumber</span></div><button class="btn" type="button" id="clearChat">Bersihkan</button></div><div class="chat-thread" id="chatThread" aria-live="polite">${state.chatMessages.map(m=>`<article class="chat-message ${m.role}"><div class="chat-avatar">${m.role==='assistant'?'S':'BK'}</div><div class="chat-bubble">${m.role==='assistant'?formatAssistantMessage(m.text):`<p>${escapeHtml(m.text)}</p>`}<small>${escapeHtml(m.meta||'Pertanyaan pengguna')}</small></div></article>`).join('')}${state.chatTyping?`<article class="chat-message assistant"><div class="chat-avatar">S</div><div class="chat-bubble typing"><span></span><span></span><span></span></div></article>`:''}</div><form class="chat-compose" id="chatForm"><label for="chatInput">Tanyakan data Kabupaten Kapuas</label><div><input id="chatInput" maxlength="240" autocomplete="off" placeholder="Tanyakan fokus strategis, wilayah, OPD, atau indikator"><button class="btn primary" type="submit" ${state.chatTyping?'disabled':''}>Kirim</button></div><small>Jawaban menggunakan data dan metadata yang tersedia di SABABUKA.</small></form></section></div>`}
function pageContent(){const stateParam=new URLSearchParams(location.search).get('state');if(stateParam==='error')return `<div class="errorbox"><strong>Data belum dapat ditampilkan.</strong><p>Terjadi kendala saat memuat tampilan. Gunakan tombol muat ulang untuk mencoba kembali.</p><button class="btn" onclick="location.href=location.pathname">Muat Ulang</button></div>`;if(state.loading)return `<div class="loading-view">${Array(8).fill('<div class="skeleton"></div>').join('')}</div>`;if(!allowedPages[state.role].has(state.page))state.page=roleHome[state.role];return ({summary:meetingSummary,coordination:coordinationPage,indicators:indicatorRegistryPage,reconciliation:reconciliationPage,integration:integrationDashboard,metadata:metadataPage,'opd-inbox':opdInboxPage,map:mapPage,opd:opdPage,finance:meetingFinance,services:meetingServices,analysis:meetingAnalysis,assistant:assistantPage,alerts:alertsPage,sources:meetingSources,validation:meetingValidation,settings:settingsPage}[state.page]||meetingSummary)()}
function indicatorDetail(i){const k=indicatorKnowledge[i.id],c=sourceContracts[i.id],dataState=indicatorDataState(i),change=i.value-i.prev,improving=i.higher?change>=0:change<=0;return `<div class="detail-hero"><div><span class="eyebrow">Detail indikator strategis</span><h2>${i.name}</h2><p>${k.definition}</p></div><span class="data-seal ${dataState.tone}">${dataState.label}</span></div><div class="detail-values"><div><small>Nilai ${state.year}</small><strong>${fmt(i.value)} ${i.unit}</strong></div><div><small>Target</small><strong>${fmt(i.target)} ${i.unit}</strong></div><div><small>Perubahan</small><strong class="${improving?'trend-up':'trend-down'}">${change>=0?'+':''}${fmt(change)} ${i.unit}</strong></div></div><section class="narrative-block"><span>Interpretasi</span><p>“Pada ${state.year}, ${i.name.toLowerCase()} tercatat ${fmt(i.value)} ${i.unit}. Dibandingkan periode sebelumnya terjadi ${improving?'perbaikan':'perubahan yang perlu dicermati'} sebesar ${fmt(Math.abs(change))} ${i.unit}. Posisi saat ini ${i.status==='good'?'telah memenuhi':'belum memenuhi'} target ${fmt(i.target)} ${i.unit}. ${k.interpretation}”</p></section><dl class="parameter-list"><div><dt>Parameter</dt><dd>${k.parameter}</dd></div><div><dt>Relevansi kebijakan</dt><dd>${k.policy}</dd></div><div><dt>Sumber primer</dt><dd>${c.primary}</dd></div><div><dt>Kanal integrasi</dt><dd>${c.channel}</dd></div><div><dt>Granularitas</dt><dd>${c.granularity}</dd></div><div><dt>Status integrasi</dt><dd>${state.page==='summary'?'Terverifikasi dan tayang':c.integration}</dd></div><div><dt>Dataset rujukan</dt><dd>${k.reference}</dd></div></dl><div class="source-boundary"><strong>Jejak data</strong><p>Identitas sumber, periode, wilayah, metode, versi, waktu pembaruan, konfirmasi OPD, dan keputusan kurasi BAPPERIDA tercatat.</p></div><div class="access-scope"><strong>Batas publikasi</strong><p>Publik menerima indikator agregat dan metodologi. Data sensitif serta rekomendasi internal hanya tersedia sesuai kewenangan.</p></div>`}
function districtDetail(d){return `<div class="detail-hero"><div><span class="eyebrow">Profil geospasial terhubung</span><h2>Kecamatan ${d.name}</h2><p>Ringkasan wilayah menghubungkan statistik resmi, data sektoral OPD, dan target perencanaan tanpa melebur sumbernya.</p></div>${badge(d.score>=80?'Baik':d.score>=68?'Perlu Perhatian':'Kritis')}</div><div class="detail-values"><div><small>Indeks wilayah</small><strong>${d.score}</strong></div><div><small>Kemiskinan</small><strong>${d.poverty}%</strong></div><div><small>Stunting</small><strong>${d.stunting}%</strong></div><div><small>Jalan mantap</small><strong>${d.roads}%</strong></div></div><section class="narrative-block"><span>Narasi wilayah</span><p>“Profil ${d.name} memperlihatkan hubungan antara kondisi sosial ekonomi, kesehatan, dan infrastruktur. Angka perlu dibaca menurut tahun, cakupan wilayah, serta sumbernya sebelum menjadi dasar penetapan lokasi prioritas.”</p></section><div class="dataset-ledger"><div><strong>BPS dan Susenas</strong><small>Kemiskinan, rumah tangga, pendidikan, serta akses layanan dasar</small><em>Statistik resmi</em></div><div><strong>Data OPD</strong><small>Program, layanan, fasilitas, ruas jalan, dan data administrasi sektoral</small><em>Konfirmasi OPD</em></div><div><strong>BAPPENAS dan dokumen daerah</strong><small>Target pembangunan, arah kebijakan, serta indikator perencanaan</small><em>Rujukan target</em></div></div><div class="source-boundary"><strong>Aturan jika angka berbeda</strong><p>Sistem menampilkan setiap versi beserta definisi dan sumbernya. BAPPERIDA memilih angka yang layak untuk konteks perencanaan setelah OPD mengonfirmasi substansi.</p></div><div class="access-scope"><strong>Tampilan publik</strong><p>Data agregat dan metodologi dapat dipublikasikan. Data individu, data sensitif, analisis risiko rinci, dan rekomendasi internal hanya tersedia untuk pengguna berwenang.</p></div>`}
function drawer(){if(!state.drawer)return '';let [type,id]=state.drawer.split(':');if(type==='indicator'||type==='district'){const body=type==='indicator'?indicatorDetail(indicators.find(x=>x.id===id)):districtDetail(districts.find(x=>x.name===decodeURIComponent(id)));return `<div class="drawer-overlay open" id="drawerOverlay"><aside class="drawer evidence-drawer" role="dialog" aria-modal="true"><div class="drawer-head"><strong>${type==='indicator'?'Penjelasan indikator':'Detail wilayah'}</strong><button class="icon-btn" id="closeDrawer">×</button></div>${body}</aside></div>`}let content='';if(type==='opd'){const o=opds.find(x=>x.id===+id),d=opdDimensions(o);content=`<h2>${o.name}</h2><p class="topbar-meta">Capaian dibandingkan dengan target OPD sendiri</p><div class="metrics" style="grid-template-columns:1fr 1fr;margin-top:16px">${metricCard('Realisasi',fmt(d.achievement)+'%',`Target ${fmt(d.target)}%`,'blue','↗')}${metricCard('Progres',fmt(d.progress)+'%',d.status,d.status==='Tercapai'?'green':'amber','✓')}</div><div class="card" style="margin-top:14px"><h3>Dasar Pembacaan</h3><p>Selisih realisasi terhadap target: <strong>${d.gap>=0?'+':''}${fmt(d.gap)} poin</strong>.</p><p>Status ditentukan dari capaian terhadap target perangkat daerah ini, bukan dibandingkan dengan OPD lain.</p><p>Target dan realisasi telah diperiksa bersama pemilik data.</p></div><div class="card" style="margin-top:14px"><h3>Riwayat Data</h3><p>28 Agu · Pembaruan diterima</p><p>26 Agu · Definisi dan periode diperiksa</p><p>22 Agu · Sinkronisasi sumber berhasil</p></div>`}else if(type==='alert'){const a=alerts.find(x=>x.id===+id),actions=state.role==='bapperida'?`<div style="display:flex;gap:8px;margin-top:14px;flex-wrap:wrap"><button class="btn soft" data-action="reviewAlert">Validasi BAPPERIDA</button><button class="btn" data-action="forwardAlert">Minta Konfirmasi OPD</button><button class="btn primary" data-action="escalateAlert">Eskalasi ke Pimpinan</button><button class="btn" data-action="resolveAlert">Tutup Peringatan</button></div>`:`<div class="read-only-note">Tampilan pimpinan bersifat baca-saja. Validasi dan eskalasi dilakukan pada Ruang BAPPERIDA.</div>`;content=`<h2>${a.title}</h2><p>${badge(a.urgency)} ${badge(a.status)}</p><div class="card"><strong>${a.opd}</strong><p class="topbar-meta">Jenis: ${a.type} · ${a.time}</p><p>Peringatan telah membawa sumber, konteks, dan status pemeriksaan sebelum digunakan dalam pembahasan pimpinan.</p></div><div class="card" style="margin-top:12px"><h3>Timeline Tindak Lanjut</h3><p>07.14 WIB · Peringatan terdeteksi</p><p>07.19 WIB · Masuk antrean validasi BAPPERIDA</p><p>${a.status==='Ditinjau'?'Sudah ditinjau · Siap menjadi bahan perhatian pimpinan':'Menunggu · Konfirmasi produsen data'}</p></div>${actions}`}else if(type==='validation'&&state.role==='bapperida'){const v=validations.find(x=>x.id===+id);content=`<h2>Periksa ${v.indicator}</h2><p class="topbar-meta">${v.opd} · ${v.source}</p><div class="metrics" style="grid-template-columns:1fr 1fr;margin-top:16px">${metricCard('Nilai Sebelumnya',v.prev,'Periode sebelumnya','blue','←')}${metricCard('Nilai Terbaru',v.latest,`Perubahan ${v.change}`,'amber','→')}</div><div class="card" style="margin-top:14px"><h3>Catatan Validator</h3><textarea id="validatorNote" style="width:100%;min-height:100px;border:1px solid var(--line);border-radius:10px;padding:10px" placeholder="Tambahkan catatan pemeriksaan..."></textarea></div><div style="display:flex;gap:8px;margin-top:14px;flex-wrap:wrap"><button class="btn primary" data-action="approveValidation">Setujui</button><button class="btn" data-action="fixValidation">Minta Perbaikan</button><button class="btn danger" data-action="rejectValidation">Tolak</button></div>`}return `<div class="drawer-overlay open" id="drawerOverlay"><aside class="drawer" role="dialog" aria-modal="true"><div class="drawer-head"><strong>Detail</strong><button class="icon-btn" id="closeDrawer">×</button></div>${content}</aside></div>`}
function searchModal(){return `<div class="modal-overlay" id="searchModal"><div class="modal"><div class="drawer-head"><strong>Pencarian Dashboard</strong><button class="icon-btn" data-close-modal>×</button></div><input class="search" id="globalSearch" style="width:100%" autofocus placeholder="Cari indikator, OPD, kecamatan, atau menu"><div id="searchResults" style="margin-top:12px"><div class="empty">Ketik kata kunci untuk mencari seluruh dashboard.</div></div></div></div>`}
function syncYearView(){const period=document.querySelector('.period');if(period)period.textContent=fixedPeriodPages.has(state.page)?'Data per Agustus 2026':`Periode Agustus ${state.year}`;if(state.page==='finance'){const values=document.querySelectorAll('.finance-grid .value');if(values.length>=4){values[0].textContent=`Rp${fmt(finance.income)} T`;values[1].textContent=`Rp${fmt(finance.spend)} T`;values[2].textContent=`${fmt(finance.absorption)}%`;values[3].textContent=`${fmt(finance.absorption-60)} pt`}}if(state.page==='services'){const values=document.querySelectorAll('.service-grid .value');const avg=services.reduce((sum,item)=>sum+item.time,0)/services.length;if(values[2])values[2].textContent=`${fmt(avg)} hari`}}
function render(){applyYear(state.year);if(state.year===2026)indicators.forEach((item,index)=>item.status=baseDataset.indicators[index].status);if(!allowedPages[state.role].has(state.page))state.page=roleHome[state.role];document.querySelector('#app').innerHTML=`<div class="app ${state.collapsed?'sidebar-collapsed':''} ${state.presentation?'presentation':''}">${sidebar()}<div class="mobile-overlay ${state.mobile?'open':''}" id="mobileOverlay"></div><main class="main">${header()}<div class="content">${pageContent()}</div></main>${drawer()}</div>`;syncYearView();bind();if(['summary','sources','integration'].includes(state.page)&&state.ckan.status==='memuat')setTimeout(loadKapuasCatalog,0);if(['summary','sources'].includes(state.page))setTimeout(loadBpsCatalog,0);if(state.page==='map'&&!state.geo)setTimeout(loadMapGeometry,0)}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{const requested=b.dataset.page;state.page=allowedPages[state.role].has(requested)?requested:roleHome[state.role];if(fixedPeriodPages.has(state.page)){state.year=2026;applyYear(2026)}state.mobile=false;state.loading=true;history.replaceState({},'',location.pathname+'?role='+state.role+'&page='+state.page);render();setTimeout(()=>{state.loading=false;render()},250)});document.querySelector('#collapseBtn')?.addEventListener('click',()=>{state.collapsed=!state.collapsed;render()});document.querySelector('#mobileMenu')?.addEventListener('click',()=>{state.mobile=true;render()});document.querySelector('#mobileOverlay')?.addEventListener('click',()=>{state.mobile=false;render()});document.querySelector('#yearSelect')?.addEventListener('change',e=>{state.year=+e.target.value;toast('Tahun tampilan diubah ke '+state.year);render()});document.querySelector('#yearSelect2')?.addEventListener('change',e=>{state.year=+e.target.value;render()});document.querySelector('#indicatorSelect')?.addEventListener('change',e=>{state.mapIndicator=e.target.value;state.drawer=null;render()});document.querySelectorAll('#presentationBtn,#presentationBtn2').forEach(b=>b.onclick=()=>{state.presentation=!state.presentation;state.collapsed=state.presentation;toast(state.presentation?'Mode Presentasi diaktifkan':'Mode Presentasi dinonaktifkan');render()});document.querySelector('#profile')?.addEventListener('click',e=>{if(e.target.closest('.profile-menu'))return;state.profile=!state.profile;render()});document.querySelector('#searchBtn')?.addEventListener('click',()=>{document.body.insertAdjacentHTML('beforeend',searchModal());bindSearch()});document.querySelector('#notifBtn')?.addEventListener('click',()=>{state.page=allowedPages[state.role].has('alerts')?'alerts':roleHome[state.role];state.year=2026;applyYear(2026);state.loading=false;render()});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.chartTab=b.dataset.tab;render()});document.querySelectorAll('[data-district]').forEach(b=>b.onclick=()=>{state.district=b.dataset.district;state.drawer='district:'+encodeURIComponent(b.dataset.district);render()});document.querySelectorAll('[data-detail]').forEach(b=>{b.onclick=()=>{state.drawer=b.dataset.detail;render()};b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();state.drawer=b.dataset.detail;render()}}});document.querySelector('#closeDrawer')?.addEventListener('click',()=>{state.drawer=null;render()});document.querySelector('#drawerOverlay')?.addEventListener('click',e=>{if(e.target.id==='drawerOverlay'){state.drawer=null;render()}});document.querySelector('#statusFilter')?.addEventListener('change',e=>{state.status=e.target.value;render()});document.querySelector('#opdSearch')?.addEventListener('input',e=>{state.search=e.target.value;const position=e.target.selectionStart;render();requestAnimationFrame(()=>{const input=document.querySelector('#opdSearch');if(input){input.focus();input.setSelectionRange(position,position)}})});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action));document.querySelectorAll('[data-sync]').forEach(b=>b.onclick=()=>syncOne(b));const sendChat=question=>{const text=question.trim();if(!text||state.chatTyping)return;state.chatMessages.push({role:'user',text});state.chatTyping=true;render();setTimeout(()=>{state.chatMessages.push({role:'assistant',text:chatbotReply(text),meta:'Asisten Data · Data SABABUKA · lihat jejak sumber'});state.chatTyping=false;render();requestAnimationFrame(()=>{const thread=document.querySelector('#chatThread');if(thread)thread.scrollTop=thread.scrollHeight})},550)};document.querySelector('#chatForm')?.addEventListener('submit',e=>{e.preventDefault();sendChat(document.querySelector('#chatInput').value)});document.querySelectorAll('[data-chat-prompt]').forEach(b=>b.onclick=()=>sendChat(b.dataset.chatPrompt));document.querySelector('#clearChat')?.addEventListener('click',()=>{state.chatMessages=state.chatMessages.slice(0,1);state.chatTyping=false;render()});document.onkeydown=e=>{if(e.key==='Escape'){document.querySelector('.modal-overlay')?.remove();if(state.drawer){state.drawer=null;render()}if(state.mobile){state.mobile=false;render()}}}}
function bindSearch(){const m=document.querySelector('#searchModal');m.querySelector('[data-close-modal]').onclick=()=>m.remove();m.onclick=e=>{if(e.target===m)m.remove()};const input=m.querySelector('#globalSearch'),res=m.querySelector('#searchResults');input.oninput=()=>{const q=input.value.toLowerCase().trim();if(!q){res.innerHTML='<div class="empty">Ketik kata kunci untuk mencari seluruh dashboard.</div>';return}const opdResults=state.role==='bapperida'?opds.map(o=>({name:o.name,meta:'OPD',go:()=>{m.remove();state.page='opd';state.drawer='opd:'+o.id;state.loading=false;render()}})):[],found=[...indicators.map(i=>({name:i.name,meta:i.opd,go:()=>{m.remove();state.page='summary';state.drawer='indicator:'+i.id;state.loading=false;render()}})),...opdResults,...districts.map(d=>({name:d.name,meta:'Kecamatan',go:()=>{m.remove();state.page='map';state.district=d.name;state.loading=false;render()}}))].filter(x=>x.name.toLowerCase().includes(q)).slice(0,8);res.innerHTML=found.length?found.map((x,i)=>`<button class="nav-item" style="color:var(--ink);background:#f6f8fa" data-result="${i}"><span class="nav-icon">⌕</span><span><strong>${x.name}</strong><br><small>${x.meta}</small></span></button>`).join(''):'<div class="empty">Tidak ada hasil yang cocok.</div>';res.querySelectorAll('[data-result]').forEach(b=>b.onclick=found[+b.dataset.result].go)}}
function handleAction(a){
  if(a==='report'||a==='export'){
    const text='SABABUKA BERSINAR\nBRIEF PIMPINAN KABUPATEN KAPUAS\nData per Agustus 2026\n\nFokus utama: 4 dari 8 isu lintas OPD\nPantauan strategis: 4 isu\nSinyal kritis: '+indicators.filter(i=>i.status==='critical').length+'\nIndikator terverifikasi: '+indicators.length+'\n\nFokus utama: ketahanan pangan dan cetak sawah; infrastruktur dan konektivitas; stunting dan layanan dasar; kemiskinan dan ketepatan sasaran DTSEN.\n\nSumber: BPS Kabupaten Kapuas, Satu Data Kabupaten Kapuas, dan data sektoral OPD. Data telah melalui kendali mutu dan kurasi BAPPERIDA.';
    const blob=new Blob([text],{type:'text/plain'}),url=URL.createObjectURL(blob),link=document.createElement('a');
    link.href=url;link.download=a==='report'?'brief-pimpinan-sababuka.txt':'ringkasan-keuangan-sababuka.txt';link.click();URL.revokeObjectURL(url);toast('Brief pimpinan berhasil dibuat');
  }else if(a==='reset'){state.status='Semua';state.search='';toast('Filter direset');render()
  }else if(a==='resetAll'){state.collapsed=false;state.presentation=false;state.status='Semua';state.search='';toast('Pengaturan tampilan direset');render()
  }else if(a==='syncAll'){toast('Pemeriksaan katalog resmi dimulai');setTimeout(()=>toast('BPS, Satu Data, dan sumber OPD selesai diperiksa'),900)
  }else if(['reviewAlert','forwardAlert','escalateAlert','resolveAlert'].includes(a)){const id=state.drawer?.startsWith('alert:')?+state.drawer.split(':')[1]:null,item=alerts.find(row=>row.id===id);if(item){if(a==='resolveAlert')item.status='Selesai';else if(a==='reviewAlert'||a==='escalateAlert')item.status='Ditinjau';if(a==='forwardAlert')item.confirmationRequested=true;if(a==='escalateAlert')item.escalated=true}toast(a==='reviewAlert'?'Peringatan masuk status ditinjau BAPPERIDA':a==='forwardAlert'?'Permintaan konfirmasi diteruskan ke OPD':a==='escalateAlert'?'Peringatan tervalidasi diteruskan ke Ringkasan Pimpinan':'Peringatan ditutup setelah tindak lanjut selesai');state.drawer=null;render()
  }else if(['approveValidation','fixValidation','rejectValidation'].includes(a)){
    const id=state.drawer?.startsWith('validation:')?+state.drawer.split(':')[1]:null,v=validations.find(item=>item.id===id);
    if(v)v.status=a==='approveValidation'?'Disetujui':a==='fixValidation'?'Perbaikan':'Ditolak';
    toast(a==='approveValidation'?'Persetujuan tercatat dan data siap ditayangkan':a==='fixValidation'?'Data dikembalikan kepada produsen untuk diperbaiki':'Data tidak dilanjutkan untuk publikasi');state.drawer=null;render();
  }else if(a==='metric'){toast('Rincian metrik tersedia pada halaman terkait')
  }else if(a==='help'){toast('Gunakan Mode Presentasi untuk tampilan proyektor yang lebih luas')
  }else if(a==='profile'){toast(roleInfo[state.role].label+' aktif pada sesi ini')}
}
function syncOne(btn){btn.classList.add('syncing');btn.textContent='↻ Memproses';setTimeout(()=>{const id=+btn.dataset.sync,source=sources.find(item=>item.id===id);if(source)source.last='28 Agu, 07.45';render();toast('Pemeriksaan sumber selesai dan waktu pembaruan tercatat')},700)}
document.addEventListener('change',event=>{if(event.target.id==='roleSelect'){state.role=event.target.value;state.page=roleHome[state.role];state.year=2026;applyYear(2026);state.loading=false;history.replaceState({},'',location.pathname+'?role='+state.role+'&page='+state.page);render();toast(roleInfo[state.role].label+' dibuka')}});
const qp=new URLSearchParams(location.search);if(Object.keys(roleInfo).includes(qp.get('role')))state.role=qp.get('role');if(qp.get('page')&&titleMap[qp.get('page')]&&allowedPages[state.role].has(qp.get('page')))state.page=qp.get('page');else{state.page=roleHome[state.role];history.replaceState({},'',location.pathname+'?role='+state.role+'&page='+state.page)}if(fixedPeriodPages.has(state.page)){state.year=2026;applyYear(2026)}render();setTimeout(()=>{state.loading=false;render()},350);
